        if (primitiveName) {
            console.log(chalk.gray(`   ${capitalizedType} Name: ${primitiveName}`));
        }
        if (primitiveId) {
            console.log(chalk.gray(`   ${capitalizedType} ID:   ${primitiveId}`));
        }
