    writeSuccess(`\n${title}\n`);
    writeInfo(`${'─'.repeat(80)}`);
    writeInfo(`Page ${pagination.currentPage} of ${pagination.totalPages} (${pagination.totalCount} total logs)\n`);
    if (logs.length === 0) {
        writeInfo("No logs found.");
        return;
    }
    // Reverse logs so latest appears at the bottom
    const reversedLogs = [...logs].reverse();
    reversedLogs.forEach((log, index) => {
        renderLogEntry(log, index === reversedLogs.length - 1);
    });
